var MetaListIssuesWithUnreadComments = metaquery.Query{
	Name:   "ListIssuesWithUnreadComments",
	Cmd:    ":many",
	Source: "comments.sql",
	SQL: `SELECT DISTINCT i.id, i.title, i.status
FROM zdx_issues i
JOIN zdx_comments c ON c.project_id = i.project_id AND c.target_type = 'issue' AND c.target_id = i.id
WHERE i.project_id = $1
  AND c.author_alias = ''
  AND NOT EXISTS (
    SELECT 1 FROM zdx_comment_reads r
    WHERE r.project_id = c.project_id
      AND r.target_type = c.target_type
      AND r.target_id = c.target_id
      AND r.role = $2
      AND r.last_read_at >= c.created_at
  )
ORDER BY i.id`,
	Columns: []metaquery.Column{
		{Name: "id", OriginalName: "id", GoType: "string", DBType: "text", NotNull: true, Table: "zdx_issues"},
		{Name: "title", OriginalName: "title", GoType: "string", DBType: "text", NotNull: true, Table: "zdx_issues"},
		{Name: "status", OriginalName: "status", GoType: "string", DBType: "text", NotNull: true, Table: "zdx_issues"},
	},
	Args: []metaquery.Arg{
		{Position: 1, Name: "project_id", GoType: "int32", DBType: "pg_catalog.int4", NotNull: true},
		{Position: 2, Name: "role", GoType: "string", DBType: "text", NotNull: true},
	},
}

